def is_valid_parentheses(s):
    matching = {')': '(', '}': '{', ']': '['}
    stack = []
    for i in range(len(s)):
        ch = s[i]
        if ch in matching:
            if len(stack) == 0 or stack[-1] != matching[ch]:
                return False
            stack.pop()
        else:
            stack.append(ch)
    return len(stack) == 0

def first_uniq_char(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for i in range(len(s)):
        if counts[s[i]] == 1:
            return s[i]
    return ''

def two_sum(nums, target):
    lookup = {}
    for i in range(len(nums)):
        diff = target - nums[i]
        if diff in lookup:
            return [lookup[diff], i]
        lookup[nums[i]] = i
    return []

def is_palindrome(s):
    filtered = [ch.lower() for ch in s if ch.isalnum()]
    left = 0
    right = len(filtered) - 1
    while left < right:
        if filtered[left] != filtered[right]:
            return False
        left = left + 1
        right = right - 1
    return True

def binary_search(nums, target):
    low = 0
    high = len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def max_subarray(nums):
    if not nums:
        return 0
    max_sum = nums[0]
    current_sum = nums[0]
    for i in range(1, len(nums)):
        num = nums[i]
        if current_sum + num > num:
            current_sum = current_sum + num
        else:
            current_sum = num
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum

def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    a = 0
    b = 1
    for i in range(2, n + 1):
        c = a + b
        a = b
        b = c
    return b

def count_vowels(text):
    vowels = set('aeiouAEIOU')
    count = 0
    for ch in text:
        if ch in vowels:
            count = count + 1
    return count

def reverse_words(s):
    words = s.strip().split()
    words.reverse()
    return ' '.join(words)

def fizz_buzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result
